        /**
         * Atiende una única conexión Bluetooth ya aceptada del lado Kotlin (`io`,
         * resultado de `BluetoothServerSocket.accept()`): conduce el handshake
         * UKEY2 como respondedor y recibe el archivo que transfiera el peer.
         *
         * A diferencia de [`start_receiver`] (TCP), aquí el bucle de aceptación
         * vive en Kotlin (`BluetoothServerSocket.accept()` es bloqueante, como el
         * resto de la API clásica de Bluetooth en Android): por cada conexión
         * entrante aceptada, Kotlin llama a esta función una vez, normalmente
         * desde una corrutina/hilo distinto para no bloquear la aceptación de la
         * siguiente conexión.
         */
    @Throws(MobileException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
     suspend fun `receiveOverBt`(`io`: ByteStreamIo, `downloadDir`: kotlin.String, `callback`: ReceiveCallback) {
        return uniffiRustCallAsync(
        UniffiLib.uniffi_kushare_mobile_fn_func_receive_over_bt(
        FfiConverterTypeByteStreamIo.lower(`io`),
        FfiConverterString.lower(`downloadDir`),
        FfiConverterTypeReceiveCallback.lower(`callback`),),
        { future, callback, continuation -> UniffiLib.ffi_kushare_mobile_rust_future_poll_void(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_kushare_mobile_rust_future_complete_void(future, continuation) },
        { future -> UniffiLib.ffi_kushare_mobile_rust_future_free_void(future) },
        // lift function
        { Unit },
        
        // Error FFI converter
        MobileException.ErrorHandler,
    )
    }

